package app.repositories;

import app.common.Page;
import app.entities.AuditEntry;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Stream;

/** Keeps audit_entries rows in memory, for tests and for trying the services without a database. */
public class MemoryAuditEntryRepository implements AuditEntryRepository {
    private final Map<List<Object>, AuditEntry> rows = new LinkedHashMap<>();
    private long nextId = 1;

    /** The key of a row, as a list of its key values. */
    private static List<Object> keyOf(AuditEntry row) {
        List<Object> key = new ArrayList<>();
        key.add(row.getEntryNo());
        return key;
    }

    /** Orders two keys value by value. */
    @SuppressWarnings({"unchecked", "rawtypes"})
    private static int compareKeys(List<Object> a, List<Object> b) {
        for (int index = 0; index < a.size(); index++) {
            int order = ((Comparable) a.get(index)).compareTo(b.get(index));
            if (order != 0) return order;
        }
        return 0;
    }

    private Stream<AuditEntry> visible() {
        return rows.values().stream().filter((row) -> true).sorted(Comparator.comparing(MemoryAuditEntryRepository::keyOf, MemoryAuditEntryRepository::compareKeys));
    }

    @Override
    public Optional<AuditEntry> findByEntryNo(Integer entryNo) {
        return visible().filter((row) -> Objects.equals(row.getEntryNo(), entryNo)).findFirst();
    }

    @Override
    public Page<AuditEntry> list(int offset, int limit) {
        List<AuditEntry> rows = visible().toList();
        return new Page<>(rows.stream().skip(offset).limit(limit).toList(), rows.size(), offset, limit);
    }

    @Override
    public List<AuditEntry> listByOrderId(Long orderId) {
        return visible().filter((row) -> Objects.equals(row.getOrderId(), orderId)).toList();
    }

    @Override
    public AuditEntry insert(AuditEntry entity) {
        if (entity.getEntryNo() == null) entity.setEntryNo((int) nextId++);
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public AuditEntry update(AuditEntry entity) {
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public void delete(AuditEntry entity) {
        rows.remove(keyOf(entity));
    }
}

