package app.repositories;

import app.common.Page;
import app.entities.AuditEntry;
import app.errors.ConflictException;
import jakarta.persistence.EntityManager;
import jakarta.persistence.EntityTransaction;
import jakarta.persistence.PersistenceException;
import java.util.List;
import java.util.Optional;

/** Keeps audit_entries rows in the database, through an EntityManager. A write joins the transaction already open, or commits at once. */
public class SqlAuditEntryRepository implements AuditEntryRepository {
    protected final EntityManager entityManager;

    public SqlAuditEntryRepository(EntityManager entityManager) {
        this.entityManager = entityManager;
    }

    @Override
    public Optional<AuditEntry> findByEntryNo(Integer entryNo) {
        return entityManager.createQuery("select e from AuditEntry e where e.entryNo = :entryNo", AuditEntry.class).setParameter("entryNo", entryNo)
                .getResultStream()
                .findFirst();
    }

    @Override
    public Page<AuditEntry> list(int offset, int limit) {
        List<AuditEntry> items = entityManager.createQuery("select e from AuditEntry e order by e.entryNo", AuditEntry.class)
                .setFirstResult(offset)
                .setMaxResults(limit)
                .getResultList();
        long total = entityManager.createQuery("select count(e) from AuditEntry e", Long.class).getSingleResult();
        return new Page<>(items, total, offset, limit);
    }

    @Override
    public List<AuditEntry> listByOrderId(Long orderId) {
        return entityManager.createQuery("select e from AuditEntry e where e.orderId = :orderId order by e.entryNo", AuditEntry.class).setParameter("orderId", orderId).getResultList();
    }

    @Override
    public AuditEntry insert(AuditEntry entity) {
        try {
            inTransaction(() -> {
                entityManager.persist(entity);
                entityManager.flush();
                // Reads back what the database filled: the key, defaults
                entityManager.refresh(entity);
            });
        } catch (PersistenceException error) {
            throw new ConflictException("AuditEntry", "the database refused the change: " + error.getMessage());
        }
        return entity;
    }

    @Override
    public AuditEntry update(AuditEntry entity) {
        AuditEntry[] stored = new AuditEntry[1];
        try {
            inTransaction(() -> {
                stored[0] = entityManager.merge(entity);
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("AuditEntry", "the database refused the change: " + error.getMessage());
        }
        return stored[0];
    }

    @Override
    public void delete(AuditEntry entity) {
        try {
            inTransaction(() -> {
                entityManager.remove(entityManager.contains(entity) ? entity : entityManager.merge(entity));
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("AuditEntry", "the database refused the change: " + error.getMessage());
        }
    }

    /** Runs a write in the transaction already open, or in one of its own. */
    private void inTransaction(Runnable write) {
        EntityTransaction transaction = entityManager.getTransaction();
        if (transaction.isActive()) {
            write.run();
            return;
        }
        transaction.begin();
        try {
            write.run();
            transaction.commit();
        } catch (RuntimeException error) {
            if (transaction.isActive()) transaction.rollback();
            throw error;
        }
    }
}

