    /** Checks the values against the rules of the "Order" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Order current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("user");
            if (value == null) {
                if (creating || values.containsKey("user")) errors.add(new FieldError("user", "is required"));
            } else {
                if (value instanceof String text && text.length() > 40) errors.add(new FieldError("user", "is longer than 40 characters"));
            }
        }
        {
            Object value = values.get("group");
            if (value == null) {
                if (!creating && values.containsKey("group")) errors.add(new FieldError("group", "cannot be empty"));
            } else {
                if (!(number(value).compareTo(new BigDecimal("0")) >= 0)) errors.add(new FieldError("group", "must be >= 0"));
            }
        }
        {
            Object value = values.get("customerName");
            if (value == null) {
                if (creating || values.containsKey("customerName")) errors.add(new FieldError("customerName", "is required"));
