            Object value = values.get("str");
            if (value != null) {
                if (value instanceof String text && text.length() > 10) errors.add(new FieldError("str", "is longer than 10 characters"));
            }
        }
        {
            Object value = values.get("dueDate");
            if (value == null) {
                if (creating || values.containsKey("dueDate")) errors.add(new FieldError("dueDate", "is required"));
            }
        }
        {
            Object value = values.get("kindCode");
            if (value != null) {
                if (value instanceof String text && text.length() > 10) errors.add(new FieldError("kind_code", "is longer than 10 characters"));
            }
        }
        {
            byte[] thingId = (byte[]) (values.containsKey("thingId") ? values.get("thingId") : current == null ? null : current.getThingId());
            if (thingId != null && uow.things().findById(thingId).isEmpty())
                errors.add(new FieldError("thing_id", "no Thing has this key"));
        }
        {
            Long parentId = (Long) (values.containsKey("parentId") ? values.get("parentId") : current == null ? null : current.getParentId());
            if (parentId != null && uow.order().findById(parentId).isEmpty())
                errors.add(new FieldError("parentId", "no Order has this key"));
        }
