    public ThingService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "things" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Thing current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("id");
            if (value == null) {
                if (creating || values.containsKey("id")) errors.add(new FieldError("id", "is required"));
            }
        }
        {
            Object value = values.get("tiny");
            if (value == null) {
                if (creating || values.containsKey("tiny")) errors.add(new FieldError("tiny", "is required"));
            }
        }
        {
            Object value = values.get("small");
            if (value == null) {
                if (creating || values.containsKey("small")) errors.add(new FieldError("small", "is required"));
            }
        }
        {
            Object value = values.get("big");
            if (value == null) {
                if (creating || values.containsKey("big")) errors.add(new FieldError("big", "is required"));
            }
        }
        {
            Object value = values.get("price");
            if (value == null) {
                if (creating || values.containsKey("price")) errors.add(new FieldError("price", "is required"));
            }
        }
        {
            Object value = values.get("r");
            if (value == null) {
                if (creating || values.containsKey("r")) errors.add(new FieldError("r", "is required"));
            }
        }
        {
            Object value = values.get("flag");
            if (value == null) {
                if (!creating && values.containsKey("flag")) errors.add(new FieldError("flag", "cannot be empty"));
            }
        }
        {
            Object value = values.get("born");
            if (value == null) {
                if (creating || values.containsKey("born")) errors.add(new FieldError("born", "is required"));
            }
        }
        {
            Object value = values.get("opens");
            if (value == null) {
                if (creating || values.containsKey("opens")) errors.add(new FieldError("opens", "is required"));
            }
        }
        {
            Object value = values.get("at");
            if (value == null) {
