            }
        }
        {
            Object value = values.get("data");
            if (value == null) {
                if (creating || values.containsKey("data")) errors.add(new FieldError("data", "is required"));
            }
        }
        {
            Object value = values.get("feeling");
            if (value == null) {
                if (creating || values.containsKey("feeling")) errors.add(new FieldError("feeling", "is required"));
            }
        }
        {
            Object value = values.get("code");
            if (value == null) {
                if (creating || values.containsKey("code")) errors.add(new FieldError("code", "is required"));
            } else {
                if (value instanceof String text && text.length() > 5) errors.add(new FieldError("code", "is longer than 5 characters"));
            }
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Thing", errors);
    }

