package app;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import app.common.Patch;
import app.entities.AuditEntry;
import app.entities.Order;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import app.services.AuditEntryChanges;
import app.services.AuditEntryService;
import jakarta.persistence.EntityManager;
import java.util.List;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

/** Tests of the "audit_entries" table. */
class AuditEntryTest {
    private EntityManager entityManager;
    /** The repositories over the test database, opened empty for every test */
    private SqlUnitOfWork uow;

    @BeforeEach
    void open() {
        entityManager = TestDatabase.open();
        uow = new SqlUnitOfWork(entityManager);
    }

    @AfterEach
    void close() {
        if (entityManager.getTransaction().isActive()) entityManager.getTransaction().rollback();
        entityManager.close();
    }

    @Nested
    class Repository {

        @Test
        void isStoredAndReadBack() {
            AuditEntry stored = Factories.addAuditEntry(uow, 1);
            uow.entityManager().clear();
            AuditEntry found = uow.auditEntries().findByEntryNo(stored.getEntryNo()).orElseThrow();
            assertEquals(stored.getEntryNo(), found.getEntryNo());
            if (stored.getOrderId() != null) assertEquals(1, uow.auditEntries().listByOrderId(stored.getOrderId()).size());
        }

        @Test
        void listsRowsByKey() {
            Factories.addAuditEntry(uow, 1);
            Factories.addAuditEntry(uow, 2);
            var page = uow.auditEntries().list(0, 1);
            assertEquals(2, page.total());
            assertEquals(1, page.items().size());
        }

        @Test
        void storesTheChanges() {
            AuditEntry stored = Factories.addAuditEntry(uow, 1);
            stored.setMessage("changed");
            uow.auditEntries().update(stored);
            uow.entityManager().clear();
            assertEquals("changed", uow.auditEntries().findByEntryNo(stored.getEntryNo()).orElseThrow().getMessage());
        }

        @Test
        void isDeleted() {
            AuditEntry stored = Factories.addAuditEntry(uow, 1);
            uow.auditEntries().delete(stored);
            assertTrue(uow.auditEntries().findByEntryNo(stored.getEntryNo()).isEmpty());
        }
    }

    @Nested
    class AuditEntryServiceTest {
        private final MemoryUnitOfWork uow = new MemoryUnitOfWork();

        @Test
        void createsAValidRow() {
            AuditEntryService service = new AuditEntryService(uow);
            int n = 100;
            Order parent0 = Factories.addOrder(uow, n);
            AuditEntry row = Factories.newAuditEntry(1);
            row.setOrderId(parent0.getId());
            var created = service.createAuditEntry(row);
            var found = service.getAuditEntry(created.getEntryNo());
            assertEquals(created.getEntryNo(), found.getEntryNo());
        }

        @Test
        void refusesAMissingValue() {
            AuditEntryService service = new AuditEntryService(uow);
            int n = 100;
            Order parent0 = Factories.addOrder(uow, n);
            AuditEntry row = Factories.newAuditEntry(1);
            row.setOrderId(parent0.getId());
            row.setMessage(null);
            ValidationFailedException error = assertThrows(ValidationFailedException.class, () -> service.createAuditEntry(row));
            assertEquals(List.of("message"), error.getErrors().stream().map(FieldError::field).toList());
        }

        @Test
        void refusesAMissingParent() {
            AuditEntryService service = new AuditEntryService(uow);
            int n = 100;
            Order parent0 = Factories.addOrder(uow, n);
            AuditEntry row = Factories.newAuditEntry(1);
            row.setOrderId(999999L);
            ValidationFailedException error = assertThrows(ValidationFailedException.class, () -> service.createAuditEntry(row));
            assertTrue(error.getErrors().stream().map(FieldError::field).toList().contains("orderId"));
        }

        @Test
        void saysWhenARowIsMissing() {
            AuditEntryService service = new AuditEntryService(uow);
            assertThrows(NotFoundException.class, () -> service.getAuditEntry(999999));
        }

        @Test
        void changesARow() {
            AuditEntryService service = new AuditEntryService(uow);
            int n = 100;
            Order parent0 = Factories.addOrder(uow, n);
            AuditEntry row = Factories.newAuditEntry(1);
            row.setOrderId(parent0.getId());
            var created = service.createAuditEntry(row);
            var updated = service.updateAuditEntry(created.getEntryNo(), new AuditEntryChanges(Patch.absent(), Patch.of("changed")));
            assertEquals("changed", updated.getMessage());
        }

        @Test
        void deletesARow() {
            AuditEntryService service = new AuditEntryService(uow);
            int n = 100;
            Order parent0 = Factories.addOrder(uow, n);
            AuditEntry row = Factories.newAuditEntry(1);
            row.setOrderId(parent0.getId());
            var created = service.createAuditEntry(row);
            service.deleteAuditEntry(created.getEntryNo());
            assertThrows(NotFoundException.class, () -> service.getAuditEntry(created.getEntryNo()));
        }
    }
}

