/** Rows for the tests: valid values for every column, and the rows they point to. */
final class Factories {
    private Factories() {}

    /** A valid Thing that is not stored yet; n makes its unique values differ. */
    static Thing newThing(int n) {
        Thing entity = new Thing();
        entity.setId(java.util.Arrays.copyOf(new byte[] { (byte) n }, 16));
        entity.setTiny((short) (n));
