        entity.setNum((n));
        entity.setBig((long) (n));
        entity.setPrice(new BigDecimal((n % 10000) + ".50"));
        entity.setR(n + 0.5f);
        entity.setD(n + 0.5);
        entity.setFlag(true);
        entity.setBorn(LocalDate.of(2026, 1, n % 28 + 1));
        entity.setOpens(LocalTime.of(12, n % 60));
        entity.setAt(LocalDateTime.of(2026, 1, n % 28 + 1, 12, 0));
        entity.setChanged(LocalDateTime.of(2026, 1, n % 28 + 1, 12, 0));
